<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TechSelectAI Admin</title><style>body{font-family:Inter,Arial,sans-serif;background:#f7f9fc;color:#14213d;margin:0}main{max-width:1100px;margin:auto;padding:32px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:18px}table{width:100%;border-collapse:collapse;background:#fff;margin-top:22px}th,td{padding:10px;border-bottom:1px solid #eef2f7;text-align:left}button{padding:8px 12px;border:0;border-radius:8px;background:#2563eb;color:white}a{color:#2563eb}@media(max-width:760px){.grid{grid-template-columns:1fr 1fr}}</style></head><body><main><h1>TechSelectAI Admin</h1><p><a href="/">← Site</a></p><div id="summary" class="grid"></div><h2>Products</h2><table><thead><tr><th>Product</th><th>Vendor</th><th>Category</th><th>Status</th><th>Reviewed</th></tr></thead><tbody id="products"></tbody></table><div id="msg"></div></main><script>
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':localStorage.getItem('csrf')||''};let r=await fetch(url,opt);let d=await r.json();if(r.status===401){location.href='/login';throw new Error('Sign in required')}if(!r.ok)throw new Error(d.error||'Request failed');return d}async function load(){try{let s=await api('/api/admin/summary');summary.innerHTML=Object.entries(s).map(([k,v])=>`<div class="card"><small>${k.replaceAll('_',' ')}</small><h2>${v}</h2></div>`).join('');let p=await api('/api/admin/products');products.innerHTML=p.products.map(x=>`<tr><td>${x.name}</td><td>${x.vendor||''}</td><td>${x.category||''}</td><td>${x.status}</td><td>${x.last_reviewed_at||''}</td></tr>`).join('')}catch(e){msg.textContent=e.message}}load();
</script></body></html>